package clientcertificateextractor

import (
	"net/http"
	"testing"

	"github.com/sirupsen/logrus"
)

func TestTraefikCertExtraction(t *testing.T) {
	headers := http.Header{}
	headers.Set("X-Forwarded-Tls-Client-Cert", "")

	logger := logrus.New().WithField("test", "traefik-test")
	extractor := NewTraefikClientCertificateExtractor(logger)

	crts := extractor.ExtractCertificate(headers)

	if len(crts) != 1 {
		t.Errorf("Expected 1 certificate, got %d", len(crts))
	}

	if crts[0].Subject.CommonName != "kkkk" {
		t.Errorf("Expected certificate with CN kkkk, got %s", crts[0].Subject.CommonName)
	}
}

func TestTraefikCertExtractorChain(t *testing.T) {
	headers := http.Header{}
	headers.Set("X-Forwarded-Tls-Client-Cert", ",")

	logger := logrus.New().WithField("test", "traefik-test")
	extractor := NewTraefikClientCertificateExtractor(logger)

	crts := extractor.ExtractCertificate(headers)

	if len(crts) != 2 {
		t.Errorf("Expected 2 certificates, got %d", len(crts))
	}

	if crts[0].Subject.CommonName != "chain-pem" {
		t.Errorf("Expected certificate with CN chain-pem, got %s", crts[0].Subject.CommonName)
	}

	if crts[1].Subject.CommonName != "Pure Root CA MLDSA" {
		t.Errorf("Expected certificate with CN Pure Root CA MLDSA, got %s", crts[1].Subject.CommonName)
	}
}

func TestTraefikLBCertExtractionEmpty(t *testing.T) {
	headers := http.Header{}

	logger := logrus.New().WithField("test", "traefik-test")
	extractor := NewTraefikClientCertificateExtractor(logger)

	crts := extractor.ExtractCertificate(headers)

	if len(crts) != 0 {
		t.Errorf("Expected 0 certificates, got %d", len(crts))
	}
}
